import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { FaGlobe, FaChevronDown, FaCheck, FaSearch } from 'react-icons/fa';
import styles from './LanguageSelector.module.css';
import { LANGUAGE_NAMES, RTL_LANGUAGES } from '../../services/i18n';

// Available languages with their native names and flags
const languages = [
  { code: 'en', name: 'English', flag: '🇺🇸', region: 'North America' },
  { code: 'es', name: 'Español', flag: '🇪🇸', region: 'Europe' },
  { code: 'fr', name: 'Français', flag: '🇫🇷', region: 'Europe' },
  { code: 'de', name: 'Deutsch', flag: '🇩🇪', region: 'Europe' },
  { code: 'zh', name: '中文', flag: '🇨🇳', region: 'Asia' },
  { code: 'ja', name: '日本語', flag: '🇯🇵', region: 'Asia' },
  { code: 'ar', name: 'العربية', flag: '🇸🇦', region: 'Middle East', rtl: true },
  { code: 'hi', name: 'हिन्दी', flag: '🇮🇳', region: 'Asia' },
  { code: 'pt', name: 'Português', flag: '🇧🇷', region: 'South America' },
  { code: 'ru', name: 'Русский', flag: '🇷🇺', region: 'Europe' }
];

// Group languages by region
const groupedLanguages = languages.reduce((acc, lang) => {
  if (!acc[lang.region]) {
    acc[lang.region] = [];
  }
  acc[lang.region].push(lang);
  return acc;
}, {});

const LanguageSelector = () => {
  const { i18n, t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [showNotification, setShowNotification] = useState(false);
  const [selectedView, setSelectedView] = useState('all'); // 'all' or 'region'
  const dropdownRef = useRef(null);
  const searchInputRef = useRef(null);
  
  // Get current language
  const currentLanguage = languages.find(lang => lang.code === i18n.language) || languages[0];
  
  // Filter languages based on search term
  const filteredLanguages = searchTerm.trim() === '' 
    ? languages 
    : languages.filter(lang => 
        lang.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        LANGUAGE_NAMES[lang.code]?.toLowerCase().includes(searchTerm.toLowerCase())
      );

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Focus search input when dropdown opens
  useEffect(() => {
    if (isOpen && searchInputRef.current) {
      setTimeout(() => {
        searchInputRef.current.focus();
      }, 100);
    } else {
      setSearchTerm('');
    }
  }, [isOpen]);

  // Toggle dropdown
  const toggleDropdown = () => {
    setIsOpen(!isOpen);
  };
  
  // Change language
  const changeLanguage = (langCode) => {
    if (langCode !== i18n.language) {
      i18n.changeLanguage(langCode);
      setIsOpen(false);
      
      // Store language preference
      localStorage.setItem('i18nextLng', langCode);
      
      // Show notification
      setShowNotification(true);
      setTimeout(() => setShowNotification(false), 3000);
    } else {
      setIsOpen(false);
    }
  };

  // Toggle view between all languages and grouped by region
  const toggleView = () => {
    setSelectedView(selectedView === 'all' ? 'region' : 'all');
  };
  
  return (
    <div className={styles.languageSelector} ref={dropdownRef}>
      <button 
        className={styles.languageButton} 
        onClick={toggleDropdown}
        aria-haspopup="true"
        aria-expanded={isOpen}
        aria-label={t('language.select')}
      >
        <span className={styles.currentFlag}>{currentLanguage.flag}</span>
        <span className={styles.currentLanguage}>{currentLanguage.name}</span>
        <FaChevronDown className={`${styles.chevron} ${isOpen ? styles.chevronUp : ''}`} />
      </button>
      
      {isOpen && (
        <div className={styles.dropdown} role="menu">
          <div className={styles.dropdownHeader}>
            <h3 className={styles.dropdownTitle}>{t('language.select')}</h3>
            <div className={styles.searchContainer}>
              <FaSearch className={styles.searchIcon} />
              <input
                ref={searchInputRef}
                type="text"
                className={styles.searchInput}
                placeholder={`${t('search.placeholder')}...`}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                aria-label={`${t('search.placeholder')} ${t('language.select')}`}
              />
            </div>
            <div className={styles.viewToggle}>
              <button 
                className={`${styles.viewButton} ${selectedView === 'all' ? styles.activeView : ''}`}
                onClick={() => setSelectedView('all')}
              >
                {t('common.all')}
              </button>
              <button 
                className={`${styles.viewButton} ${selectedView === 'region' ? styles.activeView : ''}`}
                onClick={() => setSelectedView('region')}
              >
                {t('common.byRegion')}
              </button>
            </div>
          </div>

          <div className={styles.dropdownContent}>
            {selectedView === 'all' ? (
              <div className={styles.languageList}>
                {filteredLanguages.length > 0 ? (
                  filteredLanguages.map((language) => (
                    <button
                      key={language.code}
                      className={`${styles.languageOption} ${language.code === i18n.language ? styles.active : ''} ${language.rtl ? styles.rtlOption : ''}`}
                      onClick={() => changeLanguage(language.code)}
                      role="menuitem"
                      aria-current={language.code === i18n.language ? 'true' : 'false'}
                    >
                      <span className={styles.flag}>{language.flag}</span>
                      <span className={styles.name}>{language.name}</span>
                      {language.code === i18n.language && (
                        <FaCheck className={styles.checkIcon} />
                      )}
                    </button>
                  ))
                ) : (
                  <div className={styles.noResults}>
                    {t('search.noResults')}
                  </div>
                )}
              </div>
            ) : (
              <div className={styles.regionGroups}>
                {Object.entries(groupedLanguages).map(([region, langs]) => {
                  const filteredRegionLangs = langs.filter(lang => 
                    searchTerm.trim() === '' || 
                    lang.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                    LANGUAGE_NAMES[lang.code]?.toLowerCase().includes(searchTerm.toLowerCase())
                  );
                  
                  if (filteredRegionLangs.length === 0) return null;
                  
                  return (
                    <div key={region} className={styles.regionGroup}>
                      <h4 className={styles.regionTitle}>{region}</h4>
                      <div className={styles.regionLanguages}>
                        {filteredRegionLangs.map((language) => (
                          <button
                            key={language.code}
                            className={`${styles.languageOption} ${language.code === i18n.language ? styles.active : ''} ${language.rtl ? styles.rtlOption : ''}`}
                            onClick={() => changeLanguage(language.code)}
                            role="menuitem"
                            aria-current={language.code === i18n.language ? 'true' : 'false'}
                          >
                            <span className={styles.flag}>{language.flag}</span>
                            <span className={styles.name}>{language.name}</span>
                            {language.code === i18n.language && (
                              <FaCheck className={styles.checkIcon} />
                            )}
                          </button>
                        ))}
                      </div>
                    </div>
                  );
                })}
                
                {Object.values(groupedLanguages).every(langs => 
                  langs.every(lang => 
                    !lang.name.toLowerCase().includes(searchTerm.toLowerCase()) &&
                    !LANGUAGE_NAMES[lang.code]?.toLowerCase().includes(searchTerm.toLowerCase())
                  )
                ) && (
                  <div className={styles.noResults}>
                    {t('search.noResults')}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      )}
      
      {/* Language change notification */}
      {showNotification && (
        <div className={styles.notification} role="alert">
          <span className={styles.notificationFlag}>{currentLanguage.flag}</span>
          <span>{t('language.changed', { language: currentLanguage.name })}</span>
        </div>
      )}
    </div>
  );
};

export default LanguageSelector;
